     *
     * @return WfActividadTransicion The current object (for fluent API support)
     * @see        addWfVariables()
     */
    public function clearWfVariables()
    {
        $this->collWfVariables = null; // important to set this to null since that means it is uninitialized
        $this->collWfVariablesPartial = null;

        return $this;
    }

