    /**
     * Initializes the collWfVariables collection.
     *
     * By default this just sets the collWfVariables collection to an empty array (like clearcollWfVariables());
     * however, you may wish to override this method in your stub class to provide setting appropriate
     * to your application -- for example, setting the initial array to the values stored in database.
     *
     * @param boolean $overrideExisting If set to true, the method call initializes
     *                                        the collection even if it is not empty
     *
     * @return void
     */
    public function initWfVariables($overrideExisting = true)
    {
        if (null !== $this->collWfVariables && !$overrideExisting) {
            return;
        }
        $this->collWfVariables = new PropelObjectCollection();
        $this->collWfVariables->setModel('WfVariable');
    }

    /**
     * Gets an array of WfVariable objects which contain a foreign key that references this object.
     *
     * If the $criteria is not null, it is used to always fetch the results from the database.
     * Otherwise the results are fetched from the database the first time, then cached.
     * Next time the same method is called without $criteria, the cached collection is returned.
     * If this WfActividadTransicion is new, it will return
     * an empty collection or the current collection; the criteria is ignored on a new object.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @return PropelObjectCollection|WfVariable[] List of WfVariable objects
     * @throws PropelException
     */
    public function getWfVariables($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collWfVariablesPartial && !$this->isNew();
        if (null === $this->collWfVariables || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collWfVariables) {
                // return empty collection
                $this->initWfVariables();
            } else {
                $collWfVariables = WfVariableQuery::create(null, $criteria)
                    ->filterByWfActividadTransicion($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collWfVariablesPartial && count($collWfVariables)) {
                      $this->initWfVariables(false);

                      foreach ($collWfVariables as $obj) {
                        if (false == $this->collWfVariables->contains($obj)) {
                          $this->collWfVariables->append($obj);
                        }
                      }

                      $this->collWfVariablesPartial = true;
                    }

                    $collWfVariables->getInternalIterator()->rewind();

                    return $collWfVariables;
                }

                if ($partial && $this->collWfVariables) {
                    foreach ($this->collWfVariables as $obj) {
                        if ($obj->isNew()) {
                            $collWfVariables[] = $obj;
                        }
                    }
                }

                $this->collWfVariables = $collWfVariables;
                $this->collWfVariablesPartial = false;
            }
        }

        return $this->collWfVariables;
    }

    /**
     * Sets a collection of WfVariable objects related by a one-to-many relationship
     * to the current object.
     * It will also schedule objects for deletion based on a diff between old objects (aka persisted)
     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $wfVariables A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return WfActividadTransicion The current object (for fluent API support)
     */
    public function setWfVariables(PropelCollection $wfVariables, PropelPDO $con = null)
    {
        $wfVariablesToDelete = $this->getWfVariables(new Criteria(), $con)->diff($wfVariables);


        $this->wfVariablesScheduledForDeletion = $wfVariablesToDelete;

        foreach ($wfVariablesToDelete as $wfVariableRemoved) {
            $wfVariableRemoved->setWfActividadTransicion(null);
        }

        $this->collWfVariables = null;
        foreach ($wfVariables as $wfVariable) {
            $this->addWfVariable($wfVariable);
        }

        $this->collWfVariables = $wfVariables;
        $this->collWfVariablesPartial = false;

        return $this;
    }

    /**
     * Returns the number of related WfVariable objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related WfVariable objects.
     * @throws PropelException
     */
    public function countWfVariables(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collWfVariablesPartial && !$this->isNew();
        if (null === $this->collWfVariables || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collWfVariables) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getWfVariables());
            }
            $query = WfVariableQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByWfActividadTransicion($this)
                ->count($con);
        }

        return count($this->collWfVariables);
    }

    /**
     * Method called to associate a WfVariable object to this object
     * through the WfVariable foreign key attribute.
     *
     * @param    WfVariable $l WfVariable
     * @return WfActividadTransicion The current object (for fluent API support)
     */
    public function addWfVariable(WfVariable $l)
    {
        if ($this->collWfVariables === null) {
            $this->initWfVariables();
            $this->collWfVariablesPartial = true;
        }

        if (!in_array($l, $this->collWfVariables->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddWfVariable($l);

            if ($this->wfVariablesScheduledForDeletion and $this->wfVariablesScheduledForDeletion->contains($l)) {
                $this->wfVariablesScheduledForDeletion->remove($this->wfVariablesScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

