                $this->wfVariablesScheduledForDeletion = clone $this->collWfVariables;
                $this->wfVariablesScheduledForDeletion->clear();
            }
            $this->wfVariablesScheduledForDeletion[]= clone $wfVariable;
            $wfVariable->setWfActividadTransicion(null);
        }

        return $this;
    }


