    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collWfActividadtransicionUsuarios) {
                foreach ($this->collWfActividadtransicionUsuarios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collWfInstancias) {
                foreach ($this->collWfInstancias as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collWfInstanciaBitacoras) {
                foreach ($this->collWfInstanciaBitacoras as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collWfVariables) {
                foreach ($this->collWfVariables as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aWfTransicion instanceof Persistent) {
              $this->aWfTransicion->clearAllReferences($deep);
            }
            if ($this->aWfActividad instanceof Persistent) {
              $this->aWfActividad->clearAllReferences($deep);
            }
            if ($this->aWfFlujo instanceof Persistent) {
              $this->aWfFlujo->clearAllReferences($deep);
            }
            if ($this->aWfEstado instanceof Persistent) {
              $this->aWfEstado->clearAllReferences($deep);
            }
            if ($this->aWfTipoActividad instanceof Persistent) {
              $this->aWfTipoActividad->clearAllReferences($deep);
            }
            if ($this->aWfScript instanceof Persistent) {
              $this->aWfScript->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collWfActividadtransicionUsuarios instanceof PropelCollection) {
            $this->collWfActividadtransicionUsuarios->clearIterator();
        }
        $this->collWfActividadtransicionUsuarios = null;
        if ($this->collWfInstancias instanceof PropelCollection) {
            $this->collWfInstancias->clearIterator();
        }
        $this->collWfInstancias = null;
        if ($this->collWfInstanciaBitacoras instanceof PropelCollection) {
            $this->collWfInstanciaBitacoras->clearIterator();
        }
        $this->collWfInstanciaBitacoras = null;
        if ($this->collWfVariables instanceof PropelCollection) {
            $this->collWfVariables->clearIterator();
        }
        $this->collWfVariables = null;
        $this->aWfTransicion = null;
        $this->aWfActividad = null;
        $this->aWfFlujo = null;
        $this->aWfEstado = null;
        $this->aWfTipoActividad = null;
        $this->aWfScript = null;
    }

